const originalConfirm=window.confirm.bind(window);
window.confirm=message=>{let translated=String(message);if(appLanguage!=='fr'){const direct=uiCatalog.get(uiKey(translated));if(direct)translated=direct[appLanguage];else for(const source of ['Une opération semblable existe déjà :','Voulez-vous vraiment enregistrer une autre opération ? Annuler permet de vérifier avant de payer deux fois dans le bilan.','Litres × prix/L ne correspond pas au montant payé.','Confirmer quand même ces valeurs ?'])translated=translated.replace(source,uiCatalog.get(source)[appLanguage]);}return originalConfirm(translated);};
